// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testRegression_property() public {
        c.initialize(address(0), address(1), 100e18, 10e18, 100, 100, bytes32(0), false, false);
        (bool successOrig, bytes memory retOrig) = address(c).call(abi.encodeWithSignature("onERC721Received(address,address,uint256,bytes)", address(0), address(0), 0, ""));
        require(successOrig, "call failed");
        bytes4 retVal = abi.decode(retOrig, (bytes4));
        assertTrue(retVal == 0x150b7a02, "Original should return ERC721TokenReceiver selector");
    }
}
